const icon=(name)=>({search:'⌕',home:'⌂',inbox:'⌄',calendar:'□',star:'☆',settings:'⚙',trash:'♲',plus:'＋'}[name]||'•');
const initialPages=[
 {id:'home',emoji:'✦',title:'Mi espacio',type:'home'},
 {id:'projects',emoji:'◫',title:'Proyectos',type:'projects'},
 {id:'notes',emoji:'✎',title:'Notas rápidas',type:'notes'},
 {id:'reading',emoji:'⌁',title:'Lista de lectura',type:'reading'}
];
const state={pages:JSON.parse(localStorage.getItem('luma-pages')||'null')||initialPages,active:localStorage.getItem('luma-active')||'home'};
const app=document.querySelector('#app');
let saveTimer;
function persist(){localStorage.setItem('luma-pages',JSON.stringify(state.pages));localStorage.setItem('luma-active',state.active);showSave('Guardado')}
function showSave(msg){const el=document.querySelector('.save-state');if(el){el.textContent=msg;clearTimeout(saveTimer);saveTimer=setTimeout(()=>el.textContent='Guardado localmente',1600)}}
function page(){return state.pages.find(p=>p.id===state.active)||state.pages[0]}
function sidebar(){return `<aside class="sidebar" aria-label="Navegación principal"><button class="workspace-switcher"><span class="avatar">LM</span><span>Mi espacio</span><span class="chev">⌄</span></button><div class="side-actions"><button class="side-action" data-command><span class="ico">${icon('search')}</span>Buscar <kbd>⌘ K</kbd></button><button class="side-action" data-new><span class="ico">${icon('plus')}</span>Nueva página</button></div><div class="section-title">Favoritos</div><nav class="nav-list">${state.pages.slice(0,2).map(navItem).join('')}</nav><div class="section-title">Privado</div><nav class="nav-list">${state.pages.slice(2).map(navItem).join('')}</nav><div class="side-bottom"><button class="side-action"><span class="ico">${icon('settings')}</span>Ajustes</button><button class="side-action"><span class="ico">${icon('trash')}</span>Papelera</button><div class="storage">1.3 MB de 5 GB<div class="bar"><span></span></div></div></div></aside>`}
function navItem(p){return `<button class="nav-item ${p.id===state.active?'active':''}" data-page="${p.id}"><span class="ico">${p.emoji}</span><span>${escapeHtml(p.title)}</span><span class="more">•••</span></button>`}
function commonTop(p){return `<header class="topbar"><button class="icon-btn mobile-menu" aria-label="Abrir menú">☰</button><span class="crumb">${p.emoji} ${escapeHtml(p.title)}</span><div class="top-actions"><span class="save-state">Guardado localmente</span><button class="ghost hide-mobile">Compartir</button><button class="icon-btn" data-command aria-label="Abrir comandos">•••</button></div></header>`}
function homeContent(){return `<div class="callout"><span class="spark">☀</span><div><strong>Buenos días.</strong><br>Este es tu centro de trabajo. Captura una idea, revisa tus prioridades y sigue avanzando.</div></div><div class="block h2"><button class="block-handle">⠿</button><div class="editable" contenteditable="true">Hoy</div></div><label class="todo"><input type="checkbox"><span contenteditable="true">Preparar la propuesta de lanzamiento</span></label><label class="todo"><input type="checkbox" checked><span contenteditable="true">Revisar las notas de la reunión</span></label><label class="todo"><input type="checkbox"><span contenteditable="true">Bloquear 30 minutos para planificar la semana</span></label><div class="block h2"><button class="block-handle">⠿</button><div class="editable" contenteditable="true">En marcha</div></div><div class="project-grid"><article class="project-card"><span class="emoji">◎</span><h3>Renovación del portafolio</h3><p>Últimos ajustes de contenido y revisión visual.</p><span class="status"><i class="dot"></i> En progreso · 72%</span></article><article class="project-card"><span class="emoji">↗</span><h3>Lanzamiento Q4</h3><p>Mensajes, calendario y materiales del equipo.</p><span class="status"><i class="dot blue"></i> En revisión</span></article><article class="project-card"><span class="emoji">◇</span><h3>Ideas para explorar</h3><p>Experimentos y oportunidades para el próximo ciclo.</p><span class="status"><i class="dot gray"></i> Sin fecha</span></article></div><div class="block"><button class="block-handle">⠿</button><div class="editable" contenteditable="true" data-placeholder="Escribe algo o usa / para insertar..."></div></div><button class="add-block" data-add>＋ Añadir bloque</button>`}
function genericContent(p){const samples={projects:['Panel de proyectos','Organiza las iniciativas activas, las próximas entregas y todo lo que está en pausa.'],notes:['Ideas sueltas','Escribe aquí antes de que se escape. Después podrás convertir cada idea en una página.'],reading:['Por leer','Guarda artículos, libros y referencias que quieras visitar más tarde.']};const s=samples[p.type]||['Página sin título','Empieza a escribir.'];return `<div class="callout"><span class="spark">${p.emoji}</span><div><strong>${s[0]}</strong><br>${s[1]}</div></div><div class="block h2"><button class="block-handle">⠿</button><div class="editable" contenteditable="true">Primer bloque</div></div><div class="block"><button class="block-handle">⠿</button><div class="editable" contenteditable="true" data-placeholder="Escribe algo o usa / para insertar..."></div></div><button class="add-block" data-add>＋ Añadir bloque</button>`}
function render(){const p=page();app.innerHTML=`<div class="app-shell">${sidebar()}<div class="mobile-backdrop"></div><main class="main">${commonTop(p)}<article class="editor"><div class="page-icon">${p.emoji}</div><input class="title-input" value="${escapeAttr(p.title)}" aria-label="Título de la página"><div class="page-meta"><span class="meta-chip">◷ Editado ahora</span><span class="meta-chip">◉ Solo yo</span></div><div class="divider"></div><section class="blocks">${p.type==='home'?homeContent():genericContent(p)}</section></article></main></div><div class="overlay hidden" role="dialog" aria-modal="true"><div class="command"><input placeholder="Buscar páginas o ejecutar una acción…" aria-label="Buscar"><div class="command-list"></div></div></div><div class="toast"></div>`;bind()}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.active=b.dataset.page;persist();render()});document.querySelectorAll('[data-command]').forEach(b=>b.onclick=openCommand);document.querySelector('[data-new]').onclick=()=>createPage();document.querySelector('.mobile-menu').onclick=()=>toggleMenu(true);document.querySelector('.mobile-backdrop').onclick=()=>toggleMenu(false);document.querySelector('.title-input').addEventListener('input',e=>{page().title=e.target.value;persist();document.querySelector('.crumb').innerHTML=`${page().emoji} ${escapeHtml(page().title)}`});document.querySelector('.topbar').classList.toggle('scrolled',scrollY>8);document.querySelectorAll('[contenteditable]').forEach(el=>el.addEventListener('input',()=>showSave('Guardando…')));document.querySelectorAll('.todo input').forEach(el=>el.addEventListener('change',()=>{persist();toast(el.checked?'Tarea completada':'Tarea reabierta')}));document.querySelector('[data-add]').onclick=addBlock;const overlay=document.querySelector('.overlay');overlay.onclick=e=>{if(e.target===overlay)closeCommand()}}
function hotkeys(e){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand()}else if(e.key==='Escape')closeCommand()}
function openCommand(){const overlay=document.querySelector('.overlay');overlay.classList.remove('hidden');const input=overlay.querySelector('input');drawCommands('');setTimeout(()=>input.focus(),0);input.oninput=()=>drawCommands(input.value)}
function closeCommand(){document.querySelector('.overlay')?.classList.add('hidden')}
function drawCommands(q){const list=document.querySelector('.command-list');if(!list)return;const hits=state.pages.filter(p=>p.title.toLowerCase().includes(q.toLowerCase()));list.innerHTML=`<div class="command-label">Páginas</div>${hits.map(p=>`<button class="command-item" data-go="${p.id}"><span>${p.emoji}</span>${escapeHtml(p.title)}<small>abrir</small></button>`).join('')}${q?`<button class="command-item" data-create="${escapeAttr(q)}"><span>＋</span>Crear “${escapeHtml(q)}”<small>nuevo</small></button>`:''}${!hits.length&&!q?'<div class="empty-search">No hay resultados</div>':''}`;list.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{state.active=b.dataset.go;persist();render()});list.querySelector('[data-create]')?.addEventListener('click',e=>createPage(e.currentTarget.dataset.create))}
function createPage(title='Página sin título'){const id='page-'+Date.now();state.pages.push({id,emoji:'▧',title,type:'page'});state.active=id;persist();render();setTimeout(()=>document.querySelector('.title-input').select(),0)}
function addBlock(){const wrap=document.querySelector('.blocks');const btn=document.querySelector('[data-add]');const div=document.createElement('div');div.className='block';div.innerHTML='<button class="block-handle">⠿</button><div class="editable" contenteditable="true" data-placeholder="Escribe algo o usa / para insertar..."></div>';wrap.insertBefore(div,btn);div.querySelector('.editable').focus();showSave('Guardando…')}
function toggleMenu(on){document.querySelector('.sidebar').classList.toggle('open',on);document.querySelector('.mobile-backdrop').classList.toggle('open',on)}
function toast(msg){const t=document.querySelector('.toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1700)}
function escapeHtml(s=''){return s.replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]))}
function escapeAttr(s=''){return escapeHtml(s).replace(/'/g,'&#39;')}
window.addEventListener('scroll',()=>document.querySelector('.topbar')?.classList.toggle('scrolled',scrollY>8));
window.addEventListener('keydown',hotkeys);
if(document.modelContext?.registerTool){Promise.resolve(document.modelContext.registerTool({name:'create_workspace_page',title:'Crear página',description:'Crea una nueva página en el espacio de trabajo y la abre.',inputSchema:{type:'object',properties:{title:{type:'string'}},required:['title'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:({title})=>{if(typeof title!=='string'||!title.trim())throw new Error('El título es obligatorio');createPage(title.trim());return{created:true,title:title.trim(),pageId:state.active}}})).catch(()=>{})}
render();
